  const relClasse=(v,l)=>!Number.isFinite(v)?'Não calculado':v<l[0]?'Muito baixo':v<l[1]?'Baixo':v<l[2]?'Médio':v<=l[3]?'Bom':v<=l[4]?'Alto':'Muito alto';
