  function interp(v,x,y){if(v<=x[0])return y[0];if(v>=x[x.length-1])return y[y.length-1];for(let i=1;i<x.length;i++)if(v<=x[i]){let t=(v-x[i-1])/(x[i]-x[i-1]);return y[i-1]+t*(y[i]-y[i-1])}return y[y.length-1]}
  function rodape(doc,titulo,amostra){doc.setDrawColor(215);doc.line(15,278,195,278);doc.setFont('helvetica','bold');doc.setFontSize(11);doc.setTextColor(...escuro);doc.text(titulo,15,285);doc.setFont('helvetica','normal');doc.setFontSize(8);doc.setTextColor(...cinza);doc.text(amostra,15,290);doc.text(String(doc.getNumberOfPages()),190,290,{align:'right'})}
