  function barra(doc,item,y,r){let q=faixas[item.k],v=item.v,c=item.c?item.c(v):DoCampoSoloRules.classificar(item.k,v,r),rgb=corClasse(c),vmin=Number.isFinite(item.min)?item.min:q.min,vmax=Number.isFinite(item.max)?item.max:q.max,p=clamp((v-vmin)/(vmax-vmin),0,1);doc.setFillColor(248,250,249);doc.roundedRect(15,y,180,23,3,3,'F');doc.setFont('helvetica','bold');doc.setFontSize(12);doc.setTextColor(35);doc.text(item.n,21,y+9);doc.setFont('helvetica','normal');doc.setFontSize(7);doc.setTextColor(...cinza);doc.text(item.u||'',21,y+15);doc.setFillColor(225,231,227);doc.roundedRect(55,y+9,93,5,2,2,'F');doc.setFillColor(...rgb);doc.roundedRect(55,y+9,Math.max(2,93*p),5,2,2,'F');doc.setFont('helvetica','bold');doc.setFontSize(13);doc.setTextColor(...rgb);doc.text(fmt(v),156,y+10,{align:'center'});doc.setFontSize(8);doc.text(c,156,y+17,{align:'center'})}
  function paginaPainel(doc,r,itens,subtitulo){doc.addPage();titulo(doc,'Painel Analítico dos Atributos Químicos do Solo',subtitulo);let y=34;itens.forEach(i=>{barra(doc,i,y,r);y+=25});if(itens.some(i=>i.k==='P')){let p=DoCampoSoloRules.classificarP(r.P,r);doc.setFontSize(6.5);doc.setTextColor(...cinza);doc.text(`Fósforo: ${p.fonte} • ${p.criterio}`,15,267)}rodape(doc,'Painel Analítico dos Atributos Químicos do Solo',subtitulo)}
  async function logoData(){return new Promise(resolve=>{let im=new Image();im.onload=()=>{let c=document.createElement('canvas');c.width=im.naturalWidth;c.height=im.naturalHeight;c.getContext('2d').drawImage(im,0,0);resolve(c.toDataURL('image/png'))};im.onerror=()=>resolve(null);im.src='assets/logo.png'})}
