  function paginaRadar(doc,r,id){doc.addPage();titulo(doc,'Perfil Integrado do Equilíbrio Nutricional do Solo',id);const keys=Object.keys(referencias),cx=76,cy=103,R=54;doc.setFillColor(220,244,226);doc.circle(cx,cy,R,'F');doc.setFillColor(255,241,178);doc.circle(cx,cy,R*.70,'F');doc.setFillColor(255,218,214);doc.circle(cx,cy,R*.38,'F');doc.setDrawColor(180);for(let j=0;j<keys.length;j++){let a=-Math.PI/2+j*2*Math.PI/keys.length;doc.line(cx,cy,cx+R*Math.cos(a),cy+R*Math.sin(a));doc.setFontSize(8);doc.setTextColor(50);doc.text(keys[j],cx+(R+8)*Math.cos(a),cy+(R+8)*Math.sin(a),{align:'center'})}let pts=keys.map((k,j)=>{let val=interp(r[k],referencias[k],[2,4,10,6,2]),rr=R*val/10,a=-Math.PI/2+j*2*Math.PI/keys.length;return[cx+rr*Math.cos(a),cy+rr*Math.sin(a)]});doc.setDrawColor(8,80,145);doc.setLineWidth(.9);for(let j=0;j<pts.length;j++)doc.line(...pts[j],...pts[(j+1)%pts.length]);pts.forEach(p=>{doc.setFillColor(8,80,145);doc.circle(p[0],p[1],1.4,'F')});let vals=keys.map(k=>({k,v:interp(r[k],referencias[k],[2,4,10,6,2]),status:r[k]<referencias[k][1]?'deficiência':r[k]>referencias[k][3]?'excesso':'equilíbrio'})),distantes=vals.slice().sort((a,b)=>a.v-b.v).slice(0,3),proximos=vals.slice().sort((a,b)=>b.v-a.v).slice(0,3),disp=Math.max(...vals.map(x=>x.v))-Math.min(...vals.map(x=>x.v)),perfil=disp<=2.5?'HARMÔNICO':disp<=5?'MODERADAMENTE EQUILIBRADO':'DESUNIFORME';doc.setFillColor(247,249,248);doc.setDrawColor(220);doc.roundedRect(140,39,55,111,4,4,'FD');doc.setFont('helvetica','bold');doc.setFontSize(8);doc.setTextColor(...escuro);doc.text('PERFIL NUTRICIONAL',167.5,50,{align:'center'});doc.setFontSize(10);doc.text(perfil,167.5,59,{align:'center',maxWidth:49});doc.setFontSize(7.5);doc.text('MAIS DISTANTES DO',145,75);doc.text('EQUILÍBRIO',145,81);distantes.forEach((x,i)=>doc.text(`${i+1}º ${x.k} - ${x.status}`,145,90+i*7));doc.text('MAIS PRÓXIMOS DO',145,118);doc.text('EQUILÍBRIO',145,124);proximos.forEach((x,i)=>doc.text(`• ${x.k}`,145,133+i*6));let ly=170;[[[220,80,75],'Distante do equilíbrio'],[[238,185,40],'Faixa intermediária'],[[35,150,80],'Próximo ao equilíbrio']].forEach((l,i)=>{doc.setFillColor(...l[0]);doc.circle(35+i*58,ly,2,'F');doc.setFont('helvetica','normal');doc.setFontSize(7);doc.setTextColor(65);doc.text(l[1],39+i*58,ly+2)});doc.setFillColor(250);doc.setDrawColor(210);doc.roundedRect(12,181,186,67,3,3,'FD');textoQuebrado(doc,'Este gráfico representa o equilíbrio nutricional do solo para o cafeeiro. Quanto mais uniforme e arredondado estiver o desenho, maior tende a ser o equilíbrio nutricional da lavoura.\n\nPontos próximos ao centro, na área vermelha, indicam nutrientes mais distantes da faixa considerada ideal, podendo refletir deficiência, excesso ou desequilíbrio. Valores na área amarela merecem atenção e monitoramento. Nutrientes posicionados na área verde encontram-se em faixas mais adequadas.\n\nO objetivo não é atingir o valor máximo em todos os nutrientes, mas manter um conjunto equilibrado, favorecendo a eficiência nutricional e o desenvolvimento da lavoura.',16,190,178,8);rodape(doc,'Perfil Integrado do Equilíbrio Nutricional do Solo',id)}
  function desenharPizza(doc,cx,cy,vals,cores){try{let c=document.createElement('canvas');c.width=600;c.height=600;let g=c.getContext('2d'),ini=-Math.PI/2,total=vals.reduce((a,b)=>a+b,0)||100;vals.forEach((v,i)=>{let fim=ini+v/total*Math.PI*2;g.beginPath();g.moveTo(300,300);g.arc(300,300,285,ini,fim);g.closePath();g.fillStyle=`rgb(${cores[i].join(',')})`;g.fill();g.strokeStyle='#ffffff';g.lineWidth=4;g.stroke();ini=fim});doc.addImage(c.toDataURL('image/png'),'PNG',cx-34,cy-34,68,68);return}catch{}let ini=0;vals.forEach((v,i)=>{let fim=ini+v;doc.setFillColor(...cores[i]);for(let a=ini;a<fim;a+=.7){let a1=a*Math.PI*2/100-Math.PI/2,a2=Math.min(a+.7,fim)*Math.PI*2/100-Math.PI/2;doc.triangle(cx,cy,cx+34*Math.cos(a1),cy+34*Math.sin(a1),cx+34*Math.cos(a2),cy+34*Math.sin(a2),'F')}ini=fim})}
  function paginaCTC(doc,r,id){doc.addPage();titulo(doc,'Arquitetura Química da Capacidade de Troca Catiônica',id);let T=r.T||1,atual=[r.K_cmolc/T*100,r.Ca/T*100,r.Mg/T*100,r.Al/T*100,Math.max(0,r.HAl-r.Al)/T*100],ideal=[3,60,10,0,27],labels=['POTÁSSIO (K)','CÁLCIO (Ca)','MAGNÉSIO (Mg)','ALUMÍNIO (Al)','HIDROGÊNIO (H)'],cores=[[92,199,125],[10,92,42],[48,143,68],[229,49,49],[255,188,0]];doc.setFont('helvetica','bold');doc.setFontSize(10);doc.setTextColor(65);doc.text('Ocupação Atual da CTC',57,38,{align:'center'});doc.text('Referência Técnica Ideal',153,38,{align:'center'});desenharPizza(doc,57,83,atual,cores);desenharPizza(doc,153,83,ideal,cores);[[57,atual],[153,ideal]].forEach(([cx,vs])=>{doc.setFontSize(6.5);doc.setTextColor(0,120,55);doc.text(`% K C.T.C ${Math.round(vs[0])}%`,cx,45,{align:'center'});doc.setTextColor(10,92,42);doc.text(`% Ca ${Math.round(vs[1])}%`,cx+38,100,{align:'center'});doc.setTextColor(48,143,68);doc.text(`% Mg ${Math.round(vs[2])}%`,cx-37,104,{align:'center'});doc.setTextColor(229,49,49);doc.text(`% Al ${Math.round(vs[3])}%`,cx-39,85,{align:'center'});doc.setTextColor(205,140,0);doc.text(`% H ${Math.round(vs[4])}%`,cx-34,62,{align:'center'})});let y=142;doc.setFontSize(9);doc.setTextColor(40);doc.text('DIAGNÓSTICO RESUMIDO DA OCUPAÇÃO DA CTC',105,y,{align:'center'});let xs=[15,52,89,126,163];atual.forEach((v,i)=>{let st=i===1?(v>=55&&v<=65?'Adequado':v<55?'Próximo do ideal':'Elevado'):i===2?(v>=10&&v<=15?'Adequado':v>15?'Elevado':'Baixo'):i===0?(v>=2&&v<=5?'Adequado':v>5?'Elevado':'Baixo'):i===3?(v<5?'Muito baixo':'Elevado'):(v<=30?'Adequado':'Elevado');doc.setFillColor(249,250,249);doc.setDrawColor(205);doc.rect(xs[i],149,32,34,'FD');doc.setFontSize(6.5);doc.setTextColor(...(i===3||i===4?[0,120,55]:[235,145,0]));doc.text(labels[i],xs[i]+16,157,{align:'center',maxWidth:29});doc.setFontSize(16);doc.text(/Adequado|Muito baixo/.test(st)?'✓':'↑',xs[i]+16,168,{align:'center'});doc.setFontSize(12);doc.setTextColor(35);doc.text(`${Math.round(v)}%`,xs[i]+16,176,{align:'center'});doc.setFontSize(6.5);doc.setTextColor(...corClasse(/Adequado|Muito baixo|Próximo/.test(st)?'Bom':'Alto'));doc.text(st,xs[i]+16,181,{align:'center'})});doc.setFillColor(250);doc.setDrawColor(205);doc.roundedRect(20,199,170,43,2,2,'FD');textoQuebrado(doc,'A Capacidade de Troca Catiônica (CTC) representa a capacidade do solo de armazenar e disponibilizar nutrientes ao cafeeiro. A comparação entre a ocupação atual e a referência técnica permite avaliar o equilíbrio químico da área.\n\nO manejo busca aumentar a participação de Cálcio, Magnésio e Potássio e reduzir a ocupação por Hidrogênio e Alumínio.',23,207,164,8);rodape(doc,'Arquitetura Química da Capacidade de Troca Catiônica',id)}
  function paginaTriangulo(doc,r,id){doc.addPage();titulo(doc,'Equilíbrio Estrutural das Bases Trocáveis Ca-Mg-K',id);let A=[105,48],B=[43,155],C=[167,155];doc.setFillColor(226,244,233);doc.setDrawColor(8,123,79);doc.setLineWidth(1.2);doc.triangle(...A,...B,...C,'FD');doc.setFont('helvetica','bold');doc.setFontSize(11);doc.setTextColor(...escuro);doc.text('Cálcio',105,40,{align:'center'});doc.text('Magnésio',37,164,{align:'right'});doc.text('Potássio',173,164);let soma=r.Ca+r.Mg+r.K_cmolc||1,ca=r.Ca/soma,mg=r.Mg/soma,k=r.K_cmolc/soma,x=ca*A[0]+mg*B[0]+k*C[0],y=ca*A[1]+mg*B[1]+k*C[1];doc.setFillColor(229,52,45);doc.setDrawColor(229,52,45);doc.circle(x,y,3.2,'F');let dados=[['Ca/Mg',r.CaMg,relClasse(r.CaMg,[.75,1.5,3,4.5,5.25])],['Mg/K',r.MgK,relClasse(r.MgK,[.75,1.5,3,4.5,5.25])],['Ca/K',r.CaK,relClasse(r.CaK,[2.25,4.5,9,13.5,15.75])]],bom=dados.every(z=>/Bom|Médio/.test(z[2]));doc.setFontSize(9);doc.setTextColor(40);doc.text('DIAGNÓSTICO RESUMIDO DO EQUILÍBRIO Ca-Mg-K',105,178,{align:'center'});let cards=[...dados,['EQUILÍBRIO',null,bom?'Bom equilíbrio':'Necessita ajustes']],xs=[20,64,108,152];cards.forEach((d,i)=>{doc.setFillColor(249);doc.setDrawColor(205);doc.rect(xs[i],184,38,32,'FD');doc.setFontSize(7);doc.setTextColor(...verde);doc.text(d[0],xs[i]+19,192,{align:'center'});doc.setFontSize(14);doc.text(/Bom|Médio|Equilíbrio/.test(d[2])?'✓':'!',xs[i]+19,202,{align:'center'});doc.setFontSize(10);doc.setTextColor(35);doc.text(d[1]==null?d[2]:fmt(d[1]),xs[i]+19,209,{align:'center',maxWidth:34});if(d[1]!=null){doc.setFontSize(6);doc.setTextColor(...verde);doc.text(d[2],xs[i]+19,214,{align:'center'})}});doc.setFillColor(250);doc.setDrawColor(205);doc.roundedRect(20,226,170,29,2,2,'FD');textoQuebrado(doc,'O triângulo representa a participação relativa de Cálcio, Magnésio e Potássio. O ponto vermelho mostra a posição atual da amostra, enquanto os cartões apresentam as relações Ca/Mg, Mg/K e Ca/K.',23,234,164,8);rodape(doc,'Equilíbrio Estrutural das Bases Trocáveis Ca-Mg-K',id)}
