    if(['K','Ca','Mg','S','B','Cu','Fe','Mn','Zn'].includes(item.k))return{tipo:'nutriente',cores:[[214,55,48],[239,142,28],[244,194,58],[40,166,88],[244,194,58],[239,142,28],[214,55,48]]};
