  function adicionarPaginas(doc,r){let id=r.amostra||'Amostra',cCaK=v=>relClasse(v,[2.25,4.5,9,13.5,15.75]),cRel=v=>relClasse(v,[.75,1.5,3,4.5,5.25]);paginaPainel(doc,r,[{k:'pH',n:'pH',u:'H2O',v:r.pH},{k:'MO',n:'MO',u:'dag/kg',v:r.MO},{k:'Al',n:'Al',u:'cmolc/dm3',v:r.Al},{k:'HAl',n:'H+Al',u:'cmolc/dm3',v:r.HAl},{k:'SB',n:'SB',u:'cmolc/dm3',v:r.SB},{k:'t',n:'t',u:'cmolc/dm3',v:r.t},{k:'T',n:'T',u:'cmolc/dm3',v:r.T},{k:'V',n:'V',u:'%',v:r.V},{k:'m',n:'m',u:'%',v:r.m}],id+' - Atributos Químicos');paginaPainel(doc,r,[{k:'P',n:'P',u:'mg/dm3',v:r.P},{k:'K',n:'K',u:'mg/dm3',v:r.K},{k:'Ca',n:'Ca',u:'cmolc/dm3',v:r.Ca},{k:'Mg',n:'Mg',u:'cmolc/dm3',v:r.Mg},{k:'S',n:'S',u:'mg/dm3',v:r.S},{k:'Ca',n:'Ca/K',u:'',v:r.CaK,min:2.25,max:15.75,c:cCaK,relacao:true},{k:'Mg',n:'Mg/K',u:'',v:r.MgK,min:.75,max:5.25,c:cRel,relacao:true},{k:'Ca',n:'Ca/Mg',u:'',v:r.CaMg,min:.75,max:5.25,c:cRel,relacao:true}],id+' - Macronutrientes e Relações');paginaPainel(doc,r,[{k:'B',n:'B',u:'mg/dm3',v:r.B},{k:'Cu',n:'Cu',u:'mg/dm3',v:r.Cu},{k:'Fe',n:'Fe',u:'mg/dm3',v:r.Fe},{k:'Mn',n:'Mn',u:'mg/dm3',v:r.Mn},{k:'Zn',n:'Zn',u:'mg/dm3',v:r.Zn}],id+' - Micronutrientes');paginaRadar(doc,r,id);paginaCTC(doc,r,id);paginaTriangulo(doc,r,id);paginaPH(doc,r,id)}
  async function gerarLista(lista,botao,nomeBase){if(!lista||!lista.length)return;let texto=botao.textContent;botao.disabled=true;botao.textContent=`Gerando ${lista.length} amostra(s)...`;try{const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'}),logo=await logoData(),capaDados={...lista[0],amostra:lista.length>1?`${lista.length} amostras analisadas`:lista[0].amostra},responsible=window.DoCampoDB?DoCampoDB.user():'',code=window.DoCampoDocumentCode?DoCampoDocumentCode.reservar('SOL',responsible):('SOL-'+Date.now()),agora=new Date(),date=[String(agora.getDate()).padStart(2,'0'),String(agora.getMonth()+1).padStart(2,'0'),agora.getFullYear()].join('-');capa(doc,capaDados,logo);lista.forEach(r=>adicionarPaginas(doc,r));const nome=(window.DoCampoDocumentCode?DoCampoDocumentCode.arquivo(`Interpretacao_Solo_${lista[0].produtor||nomeBase||lista[0].propriedade}_${date}_${code}`):`Interpretacao_Solo_${nomeBase||lista[0].propriedade}_${date}_${code}`).replace(/[^a-zA-Z0-9_.-]/g,'_')+'.pdf';await window.DoCampoPDF.salvarECompartilhar(doc.output('datauristring'),nome,'Interpretação de Solo',{typeLabel:'Interpretação de Solo',producer:lista[0].produtor||'',farm:lista[0].propriedade||'',fields:lista.map(r=>r.amostra).filter(Boolean),responsible,documentCode:code});}catch(e){console.error(e);alert('Não foi possível gerar o laudo completo. Tente novamente.')}finally{botao.disabled=false;botao.textContent=texto}}
  async function gerar(r,botao){return gerarLista([r],botao,`${r.propriedade}_${r.amostra}`)}
  async function gerarTodos(regs,meta,lab,botao){let lista=regs.map(x=>calcularImportada(x,meta,lab));return gerarLista(lista,botao,meta.propriedade+'_Todas_as_amostras')}
  function criarDocumento(lista){const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4'});capa(doc,{...lista[0],amostra:lista.length>1?`${lista.length} amostras analisadas`:lista[0].amostra},null);lista.forEach(r=>adicionarPaginas(doc,r));return doc}
  window.DoCampoSoloReport={gerar,gerarTodos,criarDocumento};
  window.addEventListener('DOMContentLoaded',()=>{let b=document.getElementById('pdf');if(b)b.onclick=()=>window.DoCampoSoloReport.gerar(window.__soloAtual||null,b)});
